class Solution:
    def findWords(self, board: List[List[str]], words: List[str]) -> List[str]:
        trie = {}
        for word in words:
            node = trie
            for ch in word:
                node = node.setdefault(ch, {})
            node['#'] = word
        m, n = len(board), len(board[0])
        result = []
        def dfs(i, j, node):
            ch = board[i][j]
            if ch not in node:
                return
            next_node = node[ch]
            if '#' in next_node:
                result.append(next_node.pop('#'))
            board[i][j] = '.'
            for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                ni, nj = i+di, j+dj
                if 0 <= ni < m and 0 <= nj < n and board[ni][nj] != '.':
                    dfs(ni, nj, next_node)
            board[i][j] = ch
            if not next_node:
                del node[ch]
        for i in range(m):
            for j in range(n):
                dfs(i, j, trie)
        return result

class Solution:
    def rob(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]
        def rob_linear(arr):
            prev, curr = 0, 0
            for num in arr:
                prev, curr = curr, max(curr, prev + num)
            return curr
        return max(rob_linear(nums[:-1]), rob_linear(nums[1:]))

